function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;}}
var PREFIX="JAH-TMBE-";
var DBTITLE="AI Backend Development Database";
var DESC="Everything an AI needs to build real backends: API servers, auth systems, background jobs, caching, and realtime features \u2014 each record a complete working technique with runnable code, honest trade-offs, and the production failure modes documented before they happen.";
var CATS=["api-servers", "auth-systems", "background-jobs", "caching", "realtime"];
